/**
 * Импорт текстовых файлов как строки.
 *
 * Vitest/Vite умеют `?raw`, но TypeScript о таком синтаксисе не знает и без
 * этого объявления `tsc --noEmit` падает на тесте, который при этом проходит.
 * Объявление нужно ровно одно на проект, поэтому оно здесь, а не в каждом
 * тесте.
 */
declare module "*.sql?raw" {
  const content: string;
  export default content;
}
